WITH RankedPosts AS (SELECT p.Id, p.Title, p.CreationDate, p.Score, p.ViewCount, ROW_NUMBER() OVER (PARTITION BY p.PostTypeId ORDER BY p.Score DESC NULLS FIRST) AS Rank FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' MONTH), UserStats AS (SELECT u.Id AS UserId, u.DisplayName, COUNT(b.Id) AS BadgeCount, COALESCE(SUM(CASE WHEN v.VoteTypeId = 2 THEN 1 ELSE 0 END), 0) AS TotalUpvotes, COALESCE(SUM(CASE WHEN v.VoteTypeId = 3 THEN 1 ELSE 0 END), 0) AS TotalDownvotes FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId LEFT JOIN Votes AS v ON u.Id = v.UserId GROUP BY u.Id, u.DisplayName), PostComments AS (SELECT c.PostId, COUNT(c.Id) AS CommentCount, GROUP_CONCAT(c.Text, '; ') AS Comments FROM Comments AS c GROUP BY c.PostId) SELECT rp.Title, rp.CreationDate, rp.Score, rp.ViewCount, us.DisplayName, us.BadgeCount, us.TotalUpvotes, us.TotalDownvotes, pc.CommentCount, pc.Comments FROM RankedPosts AS rp LEFT JOIN UserStats AS us ON rp.Id = us.UserId LEFT JOIN PostComments AS pc ON rp.Id = pc.PostId WHERE rp.Rank <= 5 ORDER BY rp.Score DESC NULLS FIRST, rp.ViewCount DESC NULLS FIRST LIMIT 10